package com.globalretail.shop.controller;

import com.globalretail.shop.dto.DisplaySettingsDto;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpSession;
import org.springframework.http.ResponseEntity;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.session.Session;
import org.springframework.session.SessionRepository;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/session/state")
public class SessionPreferencesController {

    private final SessionRepository<? extends Session> sessionRepository;

    public SessionPreferencesController(SessionRepository<? extends Session> sessionRepository) {
        this.sessionRepository = sessionRepository;
    }

    @PutMapping("/{sessionId}/display-settings")
    public ResponseEntity<String> updateDisplaySettings(
            @PathVariable String sessionId,
            @RequestBody DisplaySettingsDto settingsDto,
            HttpServletRequest request) {
        HttpSession currentHttpSession = request.getSession(false);
        if (currentHttpSession == null || !currentHttpSession.getId().equals(sessionId)) {
            throw new AccessDeniedException("Cannot alter preferences of another active session");
        }
        Session session = sessionRepository.findById(sessionId);
        if (session == null) {
            return ResponseEntity.notFound().build();
        }
        session.setAttribute("preferredLanguage", settingsDto.getPreferredLanguage());
        session.setAttribute("compactMode", settingsDto.isCompactMode());
        sessionRepository.save(session);
        return ResponseEntity.ok("Session preferences saved");
    }
}
